const __aivicBundle_11_sendConfirmationEmailAndLogFailure = (() => {
  async function sendConfirmationEmailAndLogFailure(input: {
    user_id: string;
    user_name?: string;
    user_email: string;
    manager_email: string;
    yesterday_work: string;
    today_plan: string;
    current_issue: string;
    report_date: string;
    sent_at: string;
  }): Promise<void> {
    const {
      user_id,
      user_name,
      user_email,
      manager_email,
      yesterday_work,
      today_plan,
      current_issue,
      report_date,
      sent_at,
    } = input;
  
    // メール送信（送信者本人と部長の両者へ）
    const emailSubject = `日報確認: ${report_date}`;
    const emailBody = `
  ユーザーID: ${user_id}
  ユーザー名: ${user_name || ''}
  昨日の実績: ${yesterday_work}
  本日の予定: ${today_plan}
  現在の課題: ${current_issue}
  報告日: ${report_date}
  送信時刻: ${sent_at}
    `.trim();
  
    // 送信者本人へのメール送信
    const userEmailResponse = await fetch('/api/send-email', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        to: user_email,
        subject: emailSubject,
        body: emailBody,
      }),
    });
  
    if (!userEmailResponse.ok) {
      throw new Error('送信者へのメール送信に失敗しました');
    }
  
    // 部長へのメール送信
    const managerEmailResponse = await fetch('/api/send-email', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        to: manager_email,
        subject: emailSubject,
        body: emailBody,
      }),
    });
  
    if (!managerEmailResponse.ok) {
      throw new Error('部長へのメール送信に失敗しました');
    }
  
    // メール送信ログレコードの保存
    const logResponse = await fetch('/api/save-email-log', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        user_id,
        user_email,
        manager_email,
        report_date,
        sent_at,
        status: 'sent',
      }),
    });
  
    if (!logResponse.ok) {
      throw new Error('ログ保存に失敗しました');
    }
  }
  return { sendConfirmationEmailAndLogFailure };
})();
export const sendConfirmationEmailAndLogFailure = __aivicBundle_11_sendConfirmationEmailAndLogFailure.sendConfirmationEmailAndLogFailure;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendConfirmationEmailAndLogFailure */

